style.css:
@-moz-document url-prefix("https://sesame.aleda.fr") {
/*
* Author        :  Alexandre Miljković
* URL           :  https://userstyles.org/styles/166154/tapa-aleda-css
* Title         :  Sésame Aleda CSS
* Version       :  2.0.3
*/

/* On remonte le bouton Continuer tout en haut de la page messages */
#app-content { position:relative }
#app-content > div.center { position:absolute; top:0; background:#fecc38; padding:1em 0; width:100%; margin-left:-7px }

/* On redescend le bouton Informations utilisateur */
.layout-rightpanel .layout-rightpanel-button { top:auto; bottom:100px }

/* Mise en avant du lien CSV */
img[src="/Tapa/javax.faces.resource/excel.png.jsf?ln=images"], img[src="/Tapa/javax.faces.resource/pdf.png.jsf?ln=images"] { opacity:.4 }
img[src="/Tapa/javax.faces.resource/csv.png.jsf?ln=images"] { outline:2px solid #00acb0; background:#fff; margin:0 .5em }
img[src="/Tapa/javax.faces.resource/csv.png.jsf?ln=images"]:hover { background:#00acb0 }

/* On vire les rubriques inutiles sur la page home */
.dashboard div.card { display:none }


/* Transfert de minutes, Mon compte, Ventes Démat inutiles */
#menuform\:um_tft, #menuform\:um_account, #menuform\:um_demat_filaire, #menuform\:um_demat_monetique, #menuform\:um_demat_multimedia { display:none }

/* Mauvaises appellations des recharges */
.itemProductText { display: none }
.itemProduct { padding:4px !important; border-radius:8px; }

/* Logo EC */
.card.login-panel { position:relative; }
.card.login-panel::after, .main-body::after { content:''; height:64px; background:url(https://emmaus-connect.org/logo.svg) no-repeat; width:126px; background-size:140px }
.card.login-panel::after { position:absolute; right:35%; bottom:4%; filter:brightness(0) }
.main-body::after { position:fixed; left:50px; top:26px; z-index:420; filter:brightness(0) invert(1) }

/* page catalogue produit, page produit */
.itemProduct .class_catalog_image, .class_img_product {
    display: inline-block;
    box-sizing: border-box;
    max-height:182px !important;
    width: 182px; /* Width of new image */
    height: 182px; /* Height of new image */
    padding-left: 182px; /* Equal to width of new image */;
    border-radius:4px;
    outline:4px double rgba(0, 0, 0, 0.12)
}

.itemProduct:hover { background: #dedace }

.itemProductNew { width:64px }

/* On met en rouge toutes les recharges qui ne correspondent pas à l'offre EC 
* Appels_SMS illimité 20 Go, Appels_SMS illimité 40 Go, Internet 100% Data 10 Go, Internationale, Internationale éco
*/
.itemProduct img:not(.itemProductNew):not([alt="3544165573179"]):not([alt="3544165573186"]):not([alt="3544165573162"]):not([alt="3544165553638"]):not([alt="3544165553621"]) {
background:#ead4d8 url(data:image/png;base64,) no-repeat
}

/* Appels_SMS illimité 20 Go */
img[alt="3544165573179"] {
background:url(data:image/png;base64,) no-repeat
}

/* Appels_SMS illimité 40 Go */
img[alt="3544165573186"] {
background:url(data:image/png;base64,) no-repeat
}

/* Internet 100% Data 10 Go */
img[alt="3544165573162"] {
background:url(data:image/png;base64,) no-repeat
}

/* Internationale éco 2 € */
img[alt="3544165553621"] {
background:url(data:image/png;base64,) no-repeat
}

/* Internationale 4 € */
img[alt="3544165553638"] {
background:url(data:image/png;base64,) no-repeat
}


/* Temp illimitée indisponible */
img[alt="3544165530547"] {
background: #ead4d8 url(data:image/png;base64,) no-repeat !important
}
}
